WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_proportion_base'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '基期比重', 'kp-xingce-data-proportion-base', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基期比重"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知当前数据，倒推历史上一期的部分量占整体量的比重。巨核必考点！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "材料给的是2023年的部分量、整体量及其增速。问：2022年（上一年）部分占整体的比重是多少？"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "绝对不要分别算出分子分母的基期量再去相除！用连乘拆解式："}]}, {"type": "katexBlock", "attrs": {"content": "基期比重 = 现期比重 \\times 调整因子 = \\frac{A}{B} \\times \\frac{1+b}{1+a}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（A为现期部分量，a为部分增速；B为现期整体量，b为整体增速）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出拆解公式] --> B[第一步: 算出现期比重 A/B]\nB --> C[拿着现期比重的估算值去排除极其离谱的选项]\nC --> D[第二步: 比较部分增速a和整体增速b]\nD -- a > b --> E[微调因子 < 1, 基期比重必然 小于 现期比重]\nD -- a < b --> F[微调因子 > 1, 基期比重必然 大于 现期比重]\nE --> G[在剩余选项中锁定答案]\nF --> G"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年总GDP为8000亿(增5%)。第三产业4000亿(增10%)。求2022年第三产业比重？选项：A. 48.2% B. 50.0% C. 52.3% D. 55.1%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算现期比重：A/B = 4000 / 8000 = 50%。排掉离谱干扰项。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看微调：部分增速 a(10%) > 整体增速 b(5%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定方向：说明今年比重比去年大。所以去年(基期)必定小于今年(50%)！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选项中小于 50% 且接近的只有 A (48.2%)。秒选。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "调整因子倒置：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多人记得微调因子，却把 1+a 和 1+b 写反了。记住，求基期就是除以(1+增长率)，所以部分的增速 a 会跑到分母上，整体的增速 b 因为是除法翻转跑到了分子上。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "以后只要看到基期比重题，不管三七二十一，先去算现期比重，很多时候算完现期比重，看一眼方向，选项就剩一个了。"}]}]}$$ AS jsonb), NULL, '基期比重的核心考点与实战推导。', category_node.id, CAST('["资料分析", "基期比重"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_proportion_base", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
